pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const lib = b.addStaticLibrary(.{
        .name = "jaide_v40",
        .root_source_file = .{ .path = "src/core/types.zig" },
        .target = target,
        .optimize = optimize,
    });

    lib.addIncludePath(.{ .path = "src/core" });
    lib.addIncludePath(.{ .path = "src/index" });
    lib.addIncludePath(.{ .path = "src/ranker" });
    lib.addIncludePath(.{ .path = "src/processor" });
    lib.addIncludePath(.{ .path = "src/tokenizer" });
    lib.addIncludePath(.{ .path = "src/optimizer" });
    lib.addIncludePath(.{ .path = "src/runtime" });

    lib.linkLibC();

    b.installArtifact(lib);

    const futhark_step = b.addSystemCommand(&[_][]const u8{
        "futhark", "c", "--library", "src/hw/accel/futhark_kernels.fut", "-o", "build/futhark_kernels",
    });
    futhark_step.step.dependOn(&lib.step);

    const clash_ranker = b.addSystemCommand(&[_][]const u8{
        "clash", "--verilog", "src/hw/rtl/RankerCore.hs", "-o", "build/hw/ranker_core.v",
    });
    clash_ranker.step.dependOn(&lib.step);

    const clash_ssi = b.addSystemCommand(&[_][]const u8{
        "clash", "--verilog", "src/hw/rtl/SSISearch.hs", "-o", "build/hw/ssi_search.v",
    });
    clash_ssi.step.dependOn(&lib.step);

    const circom_step = b.addSystemCommand(&[_][]const u8{
        "circom", "src/zk/inference_trace.circom", "--r1cs", "--wasm", "--sym", "-o", "build/zk",
    });
    circom_step.step.dependOn(&lib.step);

    const lean_verify = b.addSystemCommand(&[_][]const u8{
        "lean", "verification/lean/RSF_Properties.lean",
    });
    lean_verify.step.dependOn(&lib.step);

    const isabelle_verify = b.addSystemCommand(&[_][]const u8{
        "isabelle", "build", "-D", "verification/isabelle",
    });
    isabelle_verify.step.dependOn(&lib.step);

    const tla_verify = b.addSystemCommand(&[_][]const u8{
        "tlc", "verification/tla/IPC_Liveness.tla",
    });
    tla_verify.step.dependOn(&lib.step);

    const test_step = b.step("test", "Run verifications");
    test_step.dependOn(&futhark_step.step);
    test_step.dependOn(&clash_ranker.step);
    test_step.dependOn(&clash_ssi.step);
    test_step.dependOn(&circom_step.step);
    test_step.dependOn(&lean_verify.step);
    test_step.dependOn(&isabelle_verify.step);
    test_step.dependOn(&tla_verify.step);

    b.default_step.dependOn(test_step);
}
