pub const FixedPoint = packed struct {
    value: i64,
    pub fn fromFloat(f: f32) FixedPoint {
        return .{ .value = @intFromFloat(f * (1 << 32)) };
    }
    pub fn toFloat(self: FixedPoint) f32 {
        return @floatFromInt(self.value) / (1 << 32);
