const std = @import("std");
const types = @import("types.zig");

pub const ArenaAllocator = struct {
    parent_allocator: std.mem.Allocator,
    buffer: []u8,
    pos: usize = 0,

    pub fn init(parent_allocator: std.mem.Allocator, size: usize) !ArenaAllocator {
        var buffer = try parent_allocator.alloc(u8, size);
        return .{ .parent_allocator = parent_allocator, .buffer = buffer };
    }

    pub fn deinit(self: *ArenaAllocator) void {
        self.parent_allocator.free(self.buffer);
    }

    pub fn allocator(self: *ArenaAllocator) std.mem.Allocator {
        return .{
            .ptr = self,
            .vtable = &.{
                .alloc = alloc,
                .resize = resize,
                .free = free,
            },
        };
    }

    fn alloc(ctx: *anyopaque, len: usize, ptr_align: u8, ret_addr: usize) ?[*]u8 {
        _ = ret_addr;
        const self: *ArenaAllocator = @ptrCast(@alignCast(ctx));
        const align_mask = (@as(usize, 1) << @intCast(ptr_align)) - 1;
        const aligned_pos = (self.pos + align_mask) & ~align_mask;
        if (aligned_pos + len > self.buffer.len) return null;
        const ptr = self.buffer.ptr + aligned_pos;
        self.pos = aligned_pos + len;
        return ptr;
    }

    fn resize(ctx: *anyopaque, buf: []u8, buf_align: u8, new_len: usize, ret_addr: usize) bool {
        _ = buf_align;
        _ = ret_addr;
        const self: *ArenaAllocator = @ptrCast(@alignCast(ctx));
        if (buf.ptr + buf.len != self.buffer.ptr + self.pos) return false;
        if (new_len > buf.len) {
            const additional = new_len - buf.len;
            if (self.pos + additional > self.buffer.len) return false;
            self.pos += additional;
        } else if (new_len < buf.len) {
            self.pos -= (buf.len - new_len);
        }
        return true;
    }

    fn free(ctx: *anyopaque, buf: []u8, buf_align: u8, ret_addr: usize) void {
        _ = buf_align;
        _ = ret_addr;
        const self: *ArenaAllocator = @ptrCast(@alignCast(ctx));
        if (buf.ptr + buf.len == self.buffer.ptr + self.pos) {
            self.pos -= buf.len;
        }
    }
};

pub fn zeroCopyPass(src: []const u8, dest: *[]u8) void {
    dest.* = @constCast(src);
}
