const std = @import("std");
const types = @import("types.zig");
const memory = @import("memory.zig");

pub const TensorOps = struct {
    pub fn add(a: types.Tensor, b: types.Tensor) !types.Tensor {
        if (!std.mem.eql(usize, a.shape, b.shape)) return error.ShapeMismatch;
        var result = try types.Tensor.init(a.allocator, a.shape);
        for (0..a.data.len) |i| {
            result.data[i] = a.data[i] + b.data[i];
        }
        return result;
    }

    pub fn sub(a: types.Tensor, b: types.Tensor) !types.Tensor {
        if (!std.mem.eql(usize, a.shape, b.shape)) return error.ShapeMismatch;
        var result = try types.Tensor.init(a.allocator, a.shape);
        for (0..a.data.len) |i| {
            result.data[i] = a.data[i] - b.data[i];
        }
        return result;
    }

    pub fn mul(a: types.Tensor, b: types.Tensor) !types.Tensor {
        if (!std.mem.eql(usize, a.shape, b.shape)) return error.ShapeMismatch;
        var result = try types.Tensor.init(a.allocator, a.shape);
        for (0..a.data.len) |i| {
            result.data[i] = a.data[i] * b.data[i];
        }
        return result;
    }

    pub fn div(a: types.Tensor, b: types.Tensor) !types.Tensor {
        if (!std.mem.eql(usize, a.shape, b.shape)) return error.ShapeMismatch;
        var result = try types.Tensor.init(a.allocator, a.shape);
        for (0..a.data.len) |i| {
            if (b.data[i] == 0) return error.DivisionByZero;
            result.data[i] = a.data[i] / b.data[i];
        }
        return result;
    }

    pub fn matmul(a: types.Tensor, b: types.Tensor) !types.Tensor {
        if (a.shape.len != 2 or b.shape.len != 2 or a.shape[1] != b.shape[0]) return error.InvalidMatrixMul;
        var result = try types.Tensor.init(a.allocator, &.{a.shape[0], b.shape[1]});
        for (0..a.shape[0]) |i| {
            for (0..b.shape[1]) |j| {
                var sum: f32 = 0.0;
                for (0..a.shape[1]) |k| {
                    sum += a.data[i * a.shape[1] + k] * b.data[k * b.shape[1] + j];
                }
                result.data[i * b.shape[1] + j] = sum;
            }
        }
        return result;
    }

    pub fn dot(a: types.Tensor, b: types.Tensor) !f32 {
        if (a.shape.len != 1 or b.shape.len != 1 or a.shape[0] != b.shape[0]) return error.InvalidDot;
        var sum: f32 = 0.0;
        for (0..a.shape[0]) |i| {
            sum += a.data[i] * b.data[i];
        }
        return sum;
    }
};
