const std = @import("std");
const types = @import("../core/types.zig");
const memory = @import("../core/memory.zig");

pub const SSI = struct {
    allocator: std.mem.Allocator,
    tree: std.AutoHashMap(u64, Segment),
    mmap_file: std.fs.File,
    mmap_ptr: [*]u8,
    mmap_size: usize,

    const Segment = struct {
        start: usize,
        end: usize,
        hash: u64,
    };

    pub fn init(allocator: std.mem.Allocator, capacity: usize) !SSI {
        var file = try std.fs.cwd().createFile("ssi.db", .{ .read = true, .truncate = false });
        try file.seekTo(capacity - 1);
        _ = try file.write(&[_]u8{0});
        try file.seekTo(0);
        const mmap_ptr = try std.os.mmap(null, capacity, std.os.PROT.READ | std.os.PROT.WRITE, std.os.MAP.SHARED, file.handle, 0);
        return .{ .allocator = allocator, .tree = std.AutoHashMap(u64, Segment).init(allocator), .mmap_file = file, .mmap_ptr = mmap_ptr, .mmap_size = capacity };
    }

    pub fn deinit(self: *SSI) void {
        std.os.munmap(self.mmap_ptr[0..self.mmap_size]);
        self.mmap_file.close();
        self.tree.deinit();
    }

    pub fn addSequence(self: *SSI, tokens: []const u32) !void {
        const hash = hashSequence(tokens);
        const start = @atomicLoad(usize, &self.mmap_size, .Monotonic) - tokens.len * @sizeOf(u32);
        @memcpy(self.mmap_ptr[start..start + tokens.len * @sizeOf(u32)], std.mem.asBytes(tokens));
        try self.tree.put(hash, .{ .start = start, .end = start + tokens.len * @sizeOf(u32), .hash = hash });
    }

    pub fn retrieveSegments(self: *SSI, query: []const u32, k: usize) ![]Segment {
        const query_hash = hashSequence(query);
        var results = try self.allocator.alloc(Segment, k);
        var iter = self.tree.iterator();
        var count: usize = 0;
        while (iter.next()) |entry| {
            if (hammingDistance(query_hash, entry.value_ptr.hash) < 10 and count < k) {
                results[count] = entry.value_ptr.*;
                count += 1;
            }
        }
        return results[0..count];
    }

    fn hashSequence(tokens: []const u32) u64 {
        var hash: u64 = 0;
        for (tokens) |t| {
            hash = hash * 31 + t;
        }
        return hash;
    }

    fn hammingDistance(a: u64, b: u64) usize {
        return @popCount(a ^ b);
    }
};
