const std = @import("std");
const types = @import("../core/types.zig");
const tensor_ops = @import("../core/tensor.zig").TensorOps;

pub const RSF = struct {
    allocator: std.mem.Allocator,
    layers: usize,

    pub fn init(allocator: std.mem.Allocator, layers: usize) RSF {
        return .{ .allocator = allocator, .layers = layers };
    }

    pub fn forward(self: *RSF, window: types.ContextWindow) !types.Tensor {
        var state = try types.Tensor.init(self.allocator, &.{window.width});
        for (window.tokens, 0..) |t, i| {
            state.data[i] = @floatFromInt(t);
        }
        for (0..self.layers) |_| {
            var temp = try invertAdd(state, state);
            state = try invertMul(temp, temp);
        }
        return state;
    }

    pub fn backward(self: *RSF, grad: types.Tensor) !types.Tensor {
        var state = grad;
        for (0..self.layers) |_| {
            var temp = try invertMulInverse(state, state);
            state = try invertAddInverse(temp, temp);
        }
        return state;
    }

    fn invertAdd(a: types.Tensor, b: types.Tensor) !types.Tensor {
        return try tensor_ops.add(a, b);
    }

    fn invertAddInverse(y: types.Tensor, _: types.Tensor) !types.Tensor {
        var half = try y.clone();
        half.mulScalar(0.5);
        return half;
    }

    fn invertMul(a: types.Tensor, b: types.Tensor) !types.Tensor {
        return try tensor_ops.mul(a, b);
    }

    fn invertMulInverse(y: types.Tensor, _: types.Tensor) !types.Tensor {
        var sqrt = y;
        for (sqrt.data) |*v| v.* = std.math.sqrt(v.*);
        return sqrt;
    }
};
