const std = @import("std");
const types = @import("../core/types.zig");
const tensor_ops = @import("../core/tensor.zig").TensorOps;

pub const SFD = struct {
    allocator: std.mem.Allocator,
    diag_fisher: types.Tensor,
    spectral_clip: f32,

    pub fn init(allocator: std.mem.Allocator, param_size: usize, spectral_clip: f32) !SFD {
        var diag = try types.Tensor.init(allocator, &.{param_size});
        diag.fill(1.0);
        return .{ .allocator = allocator, .diag_fisher = diag, .spectral_clip = spectral_clip };
    }

    pub fn deinit(self: *SFD) void {
        self.diag_fisher.deinit();
    }

    pub fn update(self: *SFD, grad: types.Tensor, params: *types.Tensor) !void {
        var grad_sq = try tensor_ops.mul(grad, grad);
        defer grad_sq.deinit();
        self.diag_fisher.add(grad_sq);
        var inv_diag = self.diag_fisher;
        for (inv_diag.data) |*v| {
            v.* = 1.0 / std.math.max(v.*, self.spectral_clip);
        }
        var update = try tensor_ops.mul(grad, inv_diag);
        params.sub(update);
    }
};
