const std = @import("std");

pub const Scheduler = struct {
    tasks: []Task,
    allocator: std.mem.Allocator,

    const Task = struct {
        fn_ptr: *const fn () void,
        priority: u32,
        time_slice: u64,
    };

    pub fn init(allocator: std.mem.Allocator, task_count: usize) !Scheduler {
        var tasks = try allocator.alloc(Task, task_count);
        return .{ .tasks = tasks, .allocator = allocator };
    }

    pub fn deinit(self: *Scheduler) void {
        self.allocator.free(self.tasks);
    }

    pub fn addTask(self: *Scheduler, index: usize, fn_ptr: *const fn () void, priority: u32, time_slice: u64) void {
        self.tasks[index] = .{ .fn_ptr = fn_ptr, .priority = priority, .time_slice = time_slice };
    }

    pub fn run(self: *Scheduler) void {
        std.sort.block(Task, self.tasks, {}, struct {
            pub fn lessThan(_: void, lhs: Task, rhs: Task) bool {
                return lhs.priority < rhs.priority;
            }
        }.lessThan);
        for (self.tasks) |task| {
            const start = std.time.nanoTimestamp();
            task.fn_ptr();
            const elapsed = std.time.nanoTimestamp() - start;
            if (elapsed > task.time_slice) {
                std.debug.print("Task exceeded time slice\n", .{});
            }
        }
    }
};
