theory Microkernel_Security
  imports Main
begin

type_synonym cap = nat
type_synonym endpoint = nat
type_synonym msg = nat

datatype action = Invoke cap msg | Grant cap | Revoke cap

record state =
  caps :: "nat ⇒ cap set"
  endpoints :: "nat ⇒ endpoint set"
  isolation :: "nat ⇒ nat ⇒ bool"

inductive step :: "state ⇒ action ⇒ state ⇒ bool" where
  invoke: "c ∈ caps s p ⟹ isolation s p q ⟹ step s (Invoke c m) (s⦇endpoints := (endpoints s)(q := endpoints s q ∪ {m})⦈)" |
  grant: "c ∈ caps s p ⟹ step s (Grant c) (s⦇caps := (caps s)(q := caps s q ∪ {c})⦈)" |
  revoke: "c ∈ caps s p ⟹ step s (Revoke c) (s⦇caps := (caps s)(q := caps s q - {c})⦈)"

definition secure :: "state ⇒ bool" where
  "secure s ≡ ∀p q. ¬isolation s p q ⟶ (∀m. m ∈ endpoints s q ⟶ (∃c. c ∈ caps s p ∧ Invoke c m ∈ actions))"

theorem isolation_preservation:
  assumes "secure s" "step s a s'"
  shows "secure s'"
  using assms
  by (induction rule: step.induct) (auto simp: secure_def)

end
