// path: src/core/types.zig
const std = @import("std");
const Allocator = std.mem.Allocator;

pub const FixedPoint = struct {
    value: i64,
    scale: u32,

    pub fn init(value: i64, scale: u32) FixedPoint {
        return .{ .value = value, .scale = scale };
    }

    pub fn fromFloat(f: f32, scale: u32) FixedPoint {
        return .{ .value = @intFromFloat(f * @as(f32, @floatFromInt(@as(i64, 1) << @intCast(scale)))), .scale = scale };
    }

    pub fn toFloat(self: FixedPoint) f32 {
        return @as(f32, @floatFromInt(self.value)) / @as(f32, @floatFromInt(@as(i64, 1) << @intCast(self.scale)));
    }

    pub fn add(self: FixedPoint, other: FixedPoint) FixedPoint {
        const max_scale = @max(self.scale, other.scale);
        const left = self.value << @intCast(max_scale - self.scale);
        const right = other.value << @intCast(max_scale - other.scale);
        return .{ .value = left + right, .scale = max_scale };
    }

    pub fn sub(self: FixedPoint, other: FixedPoint) FixedPoint {
        const max_scale = @max(self.scale, other.scale);
        const left = self.value << @intCast(max_scale - self.scale);
        const right = other.value << @intCast(max_scale - other.scale);
        return .{ .value = left - right, .scale = max_scale };
    }

    pub fn mul(self: FixedPoint, other: FixedPoint) FixedPoint {
        const product = self.value * other.value;
        const new_scale = self.scale + other.scale;
        return .{ .value = product >> @intCast(new_scale / 2), .scale = new_scale / 2 };
    }

    pub fn div(self: FixedPoint, other: FixedPoint) FixedPoint {
        const dividend = self.value << @intCast(other.scale);
        return .{ .value = dividend / other.value, .scale = self.scale };
    }
};

pub const Tensor = struct {
    allocator: Allocator,
    shape: []usize,
    strides: []usize,
    data: []f32,

    pub fn init(allocator: Allocator, shape: []const usize) !Tensor {
        const total_size = product(shape);
        const data = try allocator.alloc(f32, total_size);
        @memset(data, 0.0);
        const strides = try computeStrides(allocator, shape);
        return .{ .allocator = allocator, .shape = try allocator.dupe(usize, shape), .strides = strides, .data = data };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
        self.allocator.free(self.data);
    }

    fn product(shape: []const usize) usize {
        var res: usize = 1;
        for (shape) |s| res *= s;
        return res;
    }

    fn computeStrides(allocator: Allocator, shape: []const usize) ![]usize {
        const strides = try allocator.alloc(usize, shape.len);
        var stride: usize = 1;
        var i = shape.len;
        while (i > 0) {
            i -= 1;
            strides[i] = stride;
            stride *= shape[i];
        }
        return strides;
    }

    pub fn get(self: *const Tensor, indices: []const usize) f32 {
        const offset = self.offset(indices);
        return self.data[offset];
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f32) void {
        const offset = self.offset(indices);
        self.data[offset] = value;
    }

    fn offset(self: *const Tensor, indices: []const usize) usize {
        var off: usize = 0;
        for (0..self.shape.len) |i| {
            off += indices[i] * self.strides[i];
        }
        return off;
    }

    pub fn view(self: *Tensor, new_shape: []const usize) !Tensor {
        if (product(self.shape) != product(new_shape)) return error.ShapeMismatch;
        const new_strides = try computeStrides(self.allocator, new_shape);
        return .{ .allocator = self.allocator, .shape = try self.allocator.dupe(usize, new_shape), .strides = new_strides, .data = self.data };
    }

    pub fn copy(self: *const Tensor, allocator: Allocator) !Tensor {
        const new_data = try allocator.alloc(f32, self.data.len);
        @memcpy(new_data, self.data);
        const new_strides = try computeStrides(allocator, self.shape);
        return .{ .allocator = allocator, .shape = try allocator.dupe(usize, self.shape), .strides = new_strides, .data = new_data };
    }

    pub fn fixedPoint(self: *const Tensor, scale: u32) ![]FixedPoint {
        const fps = try self.allocator.alloc(FixedPoint, self.data.len);
        for (0..self.data.len) |i| {
            fps[i] = FixedPoint.fromFloat(self.data[i], scale);
        }
        return fps;
    }
};

pub const ContextWindow = struct {
    allocator: Allocator,
    buffer: []u8,
    size: usize,
    pos: usize,

    pub fn init(allocator: Allocator, size: usize) !ContextWindow {
        const buffer = try allocator.alloc(u8, size);
        return .{ .allocator = allocator, .buffer = buffer, .size = size, .pos = 0 };
    }

    pub fn deinit(self: *ContextWindow) void {
        self.allocator.free(self.buffer);
    }

    pub fn add(self: *ContextWindow, data: []const u8) void {
        const len = @min(data.len, self.size - self.pos);
        @memcpy(self.buffer[self.pos..self.pos + len], data[0..len]);
        self.pos += len;
        if (self.pos == self.size) self.pos = 0;
    }

    pub fn get(self: *const ContextWindow) []u8 {
        if (self.pos == self.size) return self.buffer;
        return self.buffer[0..self.pos];
    }
};

pub const PRNG = struct {
    state: u64,

    pub fn init(seed: u64) PRNG {
        return .{ .state = seed };
    }

    pub fn next(self: *PRNG) u64 {
        self.state ^= self.state >> 12;
        self.state ^= self.state << 25;
        self.state ^= self.state >> 27;
        return self.state *% 0x2545f4914f6cdd1d;
    }

    pub fn float(self: *PRNG) f32 {
        return @as(f32, @floatFromInt(self.next() >> 32)) / @as(f32, @floatFromInt(std.math.maxInt(u32)));
    }

    pub fn int(self: *PRNG, comptime T: type) T {
        return @truncate(self.next());
    }
};
