const std = @import("std");
const Allocator = std.mem.Allocator;

pub const ArenaAllocator = struct {
    parent_allocator: Allocator,
    buffers: std.ArrayList([]u8),
    current: []u8,
    pos: usize,

    pub fn init(parent_allocator: Allocator) ArenaAllocator {
        return .{
            .parent_allocator = parent_allocator,
            .buffers = std.ArrayList([]u8).init(parent_allocator),
            .current = &.{},
            .pos = 0,
        };
    }

    pub fn deinit(self: *ArenaAllocator) void {
        for (self.buffers.items) |buf| {
            self.parent_allocator.free(buf);
        }
        self.buffers.deinit();
    }

    fn allocator(self: *ArenaAllocator) Allocator {
        return .{ .ptr = self, .vtable = &.{
            .alloc = alloc,
            .resize = resize,
            .free = free,
        } };
    }

    fn alloc(ctx: *anyopaque, len: usize, ptr_align: u8, ret_addr: usize) ?[*]u8 {
        _ = ret_addr;
        const self = @ptrCast(*ArenaAllocator, @alignCast(ctx));
        const alignment = @as(usize, 1) << @intCast(ptr_align);
        const aligned_pos = std.mem.alignForward(usize, self.pos, alignment);
        if (aligned_pos + len > self.current.len) {
            const new_size = std.math.max(std.mem.alignForward(usize, len, std.mem.page_size), self.current.len * 2);
            const new_buf = self.parent_allocator.alignedAlloc(u8, std.mem.page_size, new_size) catch return null;
            self.buffers.append(new_buf) catch return null;
            self.current = new_buf;
            self.pos = 0;
            return alloc(ctx, len, ptr_align, ret_addr);
        }
        const ptr = self.current.ptr + aligned_pos;
        self.pos = aligned_pos + len;
        return ptr;
    }

    fn resize(ctx: *anyopaque, buf: []u8, buf_align: u8, new_len: usize, ret_addr: usize) bool {
        _ = buf_align;
        _ = ret_addr;
        const self = @ptrCast(*ArenaAllocator, @alignCast(ctx));
        if (new_len > buf.len) return false;
        if (@ptrToInt(buf.ptr) + buf.len != @ptrToInt(self.current.ptr) + self.pos) return false;
        self.pos -= buf.len - new_len;
        return true;
    }

    fn free(ctx: *anyopaque, buf: []u8, buf_align: u8, ret_addr: usize) void {
        _ = ctx;
        _ = buf;
        _ = buf_align;
        _ = ret_addr;
    }
};

pub const PoolAllocator = struct {
    parent_allocator: Allocator,
    free_list: std.SinglyLinkedList([]u8),
    item_size: usize,
    alignment: usize,

    pub fn init(parent_allocator: Allocator, item_size: usize, alignment: usize) PoolAllocator {
        return .{
            .parent_allocator = parent_allocator,
            .free_list = .{},
            .item_size = item_size,
            .alignment = alignment,
        };
    }

    pub fn deinit(self: *PoolAllocator) void {
        var node = self.free_list.first;
        while (node) |n| {
            self.parent_allocator.free(n.data);
            const next = n.next;
            self.parent_allocator.destroy(n);
            node = next;
        }
    }

    fn allocator(self: *PoolAllocator) Allocator {
        return .{ .ptr = self, .vtable = &.{
            .alloc = alloc,
            .resize = resize,
            .free = free,
        } };
    }

    fn alloc(ctx: *anyopaque, len: usize, ptr_align: u8, ret_addr: usize) ?[*]u8 {
        _ = ret_addr;
        const self = @ptrCast(*PoolAllocator, @alignCast(ctx));
        if (len != self.item_size or ptr_align != self.alignment) return null;
        if (self.free_list.popFirst()) |node| {
            const buf = node.data;
            self.parent_allocator.destroy(node);
            return buf.ptr;
        }
        return (self.parent_allocator.alignedAlloc(u8, self.alignment, self.item_size) catch return null).ptr;
    }

    fn resize(ctx: *anyopaque, buf: []u8, buf_align: u8, new_len: usize, ret_addr: usize) bool {
        _ = ctx;
        _ = buf_align;
        _ = ret_addr;
        return new_len == buf.len;
    }

    fn free(ctx: *anyopaque, buf: []u8, buf_align: u8, ret_addr: usize) void {
        _ = buf_align;
        _ = ret_addr;
        const self = @ptrCast(*PoolAllocator, @alignCast(ctx));
        const node = self.parent_allocator.create(std.SinglyLinkedList([]u8).Node) catch return;
        node.data = buf;
        self.free_list.prepend(node);
    }
};

pub fn zeroCopy(src: []const u8, allocator: Allocator) ![]u8 {
    const dst = try allocator.alloc(u8, src.len);
    @memcpy(dst, src);
    return dst;
}

pub fn boundsCheck(ptr: [*]u8, len: usize, access: usize) !void {
    if (access >= len) return error.OutOfBounds;
    _ = ptr + access;
}
