pub const BufferedReader = struct {
    file: std.fs.File,
    buffer: []u8,
    pos: usize,
    end: usize,

    pub fn init(allocator: Allocator, file: std.fs.File, buffer_size: usize) !BufferedReader {
        const buffer = try allocator.alloc(u8, buffer_size);
        return .{ .file = file, .buffer = buffer, .pos = 0, .end = 0 };
    }

    pub fn deinit(self: *BufferedReader, allocator: Allocator) void {
        allocator.free(self.buffer);
    }

    pub fn read(self: *BufferedReader, dest: []u8) !usize {
        var total_read: usize = 0;
        while (total_read < dest.len) {
            if (self.pos == self.end) {
                self.end = try self.file.read(self.buffer);
                self.pos = 0;
                if (self.end == 0) break;
            }
            const avail = self.end - self.pos;
            const to_copy = @min(avail, dest.len - total_read);
            @memcpy(dest[total_read..total_read + to_copy], self.buffer[self.pos..self.pos + to_copy]);
            self.pos += to_copy;
            total_read += to_copy;
        }
        return total_read;
    }

    pub fn readLine(self: *BufferedReader, allocator: Allocator) !?[]u8 {
        var line = std.ArrayList(u8).init(allocator);
        defer line.deinit();
        while (true) {
            if (self.pos == self.end) {
                self.end = try self.file.read(self.buffer);
                self.pos = 0;
                if (self.end == 0) break;
            }
            const start = self.pos;
            while (self.pos < self.end and self.buffer[self.pos] != '\n') self.pos += 1;
            try line.appendSlice(self.buffer[start..self.pos]);
            if (self.pos < self.end and self.buffer[self.pos] == '\n') {
                self.pos += 1;
                return try line.toOwnedSlice();
            }
        }
        if (line.items.len == 0) return null;
        return try line.toOwnedSlice();
    }
};

