        const buffer = try allocator.alloc(u8, buffer_size);
        return .{ .file = file, .buffer = buffer, .pos = 0 };
    }

    pub fn deinit(self: *BufferedWriter, allocator: Allocator) void {
        self.flush() catch {};
        allocator.free(self.buffer);
    }

    pub fn write(self: *BufferedWriter, data: []const u8) !void {
        var remaining = data;
        while (remaining.len > 0) {
            if (self.pos == self.buffer.len) try self.flush();
            const to_copy = @min(remaining.len, self.buffer.len - self.pos);
            @memcpy(self.buffer[self.pos..self.pos + to_copy], remaining[0..to_copy]);
            self.pos += to_copy;
            remaining = remaining[to_copy..];
