const std = @import("std");
const math = std.math;
const mem = std.mem;
const meta = std.meta;
const rand = std.rand;

pub const Fixed3232 = packed struct {
    mantissa: u32,
    exponent: i32,

    pub fn init(value: f32) Fixed3232 {
        const exp = math.log2(value);
        const mant = @as(u32, @intFromFloat(value / math.pow(f32, 2, exp)));
        return .{ .mantissa = mant, .exponent = @intFromFloat(exp) };
    }

    pub fn toFloat(self: Fixed3232) f32 {
        return @as(f32, @floatFromInt(self.mantissa)) * math.pow(f32, 2, @as(f32, @floatFromInt(self.exponent)));
    }

    pub fn add(self: Fixed3232, other: Fixed3232) Fixed3232 {
        if (self.exponent > other.exponent) {
            const diff = self.exponent - other.exponent;
            const adjusted = .{ .mantissa = other.mantissa >> @intCast(diff), .exponent = self.exponent };
            return init(self.toFloat() + adjusted.toFloat());
        } else {
            const diff = other.exponent - self.exponent;
            const adjusted = .{ .mantissa = self.mantissa >> @intCast(diff), .exponent = other.exponent };
            return init(adjusted.toFloat() + other.toFloat());
        }
    }

    pub fn sub(self: Fixed3232, other: Fixed3232) Fixed3232 {
        return init(self.toFloat() - other.toFloat());
    }

    pub fn mul(self: Fixed3232, other: Fixed3232) Fixed3232 {
        const exp_sum = self.exponent + other.exponent;
        const mant_prod = @as(u64, self.mantissa) * other.mantissa;
        const mant = @truncate(mant_prod >> 32);
        return .{ .mantissa = mant, .exponent = exp_sum };
    }

    pub fn div(self: Fixed3232, other: Fixed3232) Fixed3232 {
        const exp_diff = self.exponent - other.exponent;
        const mant_quot = @as(u64, self.mantissa) << 32 / other.mantissa;
        const mant = @truncate(mant_quot);
        return .{ .mantissa = mant, .exponent = exp_diff };
    }
};

pub const ContextWindow = struct {
    width: usize = 4096,
    segments: []RankedSegment,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, width: usize) !ContextWindow {
        return .{ .width = width, .segments = &.{}, .allocator = allocator };
    }

    pub fn deinit(self: *ContextWindow) void {
        for (self.segments) |seg| seg.deinit();
        self.allocator.free(self.segments);
    }

    pub fn addSegment(self: *ContextWindow, segment: RankedSegment) !void {
        const new_len = self.segments.len + 1;
        try self.allocator.resize(self.segments, new_len);
        self.segments[new_len - 1] = segment;
    }

    pub fn rank(self: *ContextWindow, scores: []f32) !void {
        var indices = try self.allocator.alloc(usize, self.segments.len);
        defer self.allocator.free(indices);
        for (0..self.segments.len) |i| indices[i] = i;
        std.sort.sort(usize, indices, scores, struct {
            pub fn lessThan(_: void, a: usize, b: usize, scores: []const f32) bool {
                return scores[a] > scores[b];
            }
        }.lessThan);
        var sorted_segments = try self.allocator.alloc(RankedSegment, self.segments.len);
        defer self.allocator.free(sorted_segments);
        for (0..indices.len) |i| {
            sorted_segments[i] = self.segments[indices[i]];
        }
        self.allocator.free(self.segments);
        self.segments = sorted_segments;
    }

    pub fn extractTopK(self: *ContextWindow, k: usize) ![]RankedSegment {
        const topk = try self.allocator.alloc(RankedSegment, math.min(k, self.segments.len));
        @memcpy(topk, self.segments[0..topk.len]);
        return topk;
    }
};

pub const RankedSegment = struct {
    tokens: []u32,
    score: f32,
    position: u64,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, tokens: []u32, score: f32, position: u64) !RankedSegment {
        const copy = try allocator.dupe(u32, tokens);
        return .{ .tokens = copy, .score = score, .position = position, .allocator = allocator };
    }

    pub fn deinit(self: *RankedSegment) void {
        self.allocator.free(self.tokens);
    }

    pub fn similarity(self: *RankedSegment, other: *const RankedSegment) f32 {
        if (self.tokens.len != other.tokens.len) return 0.0;
        var dot: f32 = 0.0;
        for (0..self.tokens.len) |i| {
            dot += @as(f32, @floatFromInt(self.tokens[i])) * @as(f32, @floatFromInt(other.tokens[i]));
        }
        const norm_self = math.sqrt(@as(f32, @floatFromInt(self.tokens.len)));
        const norm_other = norm_self;
        return dot / (norm_self * norm_other);
    }
};

pub const BitSet = struct {
    bits: []u64,
    capacity: usize,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, capacity: usize) !BitSet {
        const num_words = (capacity + 63) / 64;
        const bits = try allocator.alloc(u64, num_words);
        @memset(bits, 0);
        return .{ .bits = bits, .capacity = capacity, .allocator = allocator };
    }

    pub fn deinit(self: *BitSet) void {
        self.allocator.free(self.bits);
    }

    pub fn set(self: *BitSet, index: usize) void {
        if (index >= self.capacity) return;
        const word = index / 64;
        const bit = @as(u6, @intCast(index % 64));
        self.bits[word] |= (@as(u64, 1) << bit);
    }

    pub fn unset(self: *BitSet, index: usize) void {
        if (index >= self.capacity) return;
        const word = index / 64;
        const bit = @as(u6, @intCast(index % 64));
        self.bits[word] &= ~(@as(u64, 1) << bit);
    }

    pub fn test(self: *const BitSet, index: usize) bool {
        if (index >= self.capacity) return false;
        const word = index / 64;
        const bit = @as(u6, @intCast(index % 64));
        return (self.bits[word] & (@as(u64, 1) << bit)) != 0;
    }

    pub fn count(self: *const BitSet) usize {
        var count: usize = 0;
        for (self.bits) |word| {
            count += @popCount(u64, word);
        }
        return count;
    }

    pub fn unionWith(self: *BitSet, other: *const BitSet) void {
        const min_words = math.min(self.bits.len, other.bits.len);
        for (0..min_words) |i| {
            self.bits[i] |= other.bits[i];
        }
    }

    pub fn intersectWith(self: *BitSet, other: *const BitSet) void {
        const min_words = math.min(self.bits.len, other.bits.len);
        for (0..min_words) |i| {
            self.bits[i] &= other.bits[i];
        }
    }

    pub fn difference(self: *BitSet, other: *const BitSet) void {
        const min_words = math.min(self.bits.len, other.bits.len);
        for (0..min_words) |i| {
            self.bits[i] &= ~other.bits[i];
        }
    }

    pub fn copyTo(self: *const BitSet, dest: *BitSet) void {
        const min_words = math.min(self.bits.len, dest.bits.len);
        @memcpy(dest.bits[0..min_words], self.bits[0..min_words]);
    }
};

pub const PRNG = struct {
    state: [4]u64,
    allocator: ?*mem.Allocator = null,

    pub fn init(seed: u64) PRNG {
        var prng = std.rand.Xoshiro256.init(seed);
        var state: [4]u64 = undefined;
        for (&state) |*s| s.* = prng.random().uint64();
        return .{ .state = state };
    }

    pub fn nextU64(self: *PRNG) u64 {
        var x = self.state[0];
        const y = self.state[1];
        const z = self.state[2];
        const w = self.state[3];
        const t = x ~ (x << 55);
        x = y ^ (y >> 14);
        y = z ^ (z << 36);
        z = w ^ (w >> 17);
        w = t ^ (t >> 31);
        self.state = .{ x, y, z, w };
        return x;
    }

    pub fn nextF32(self: *PRNG) f32 {
        const bits = self.nextU64();
        return @as(f32, @bitCast(@as(u32, @truncate(bits >> 32)))) / @as(f32, @floatFromInt(std.math.maxInt(u32)));
    }

    pub fn fillBytes(self: *PRNG, buf: []u8) void {
        var i: usize = 0;
        while (i + 8 <= buf.len) : (i += 8) {
            const val = self.nextU64();
            mem.writeIntLittle(u64, buf[i..][0..8], val);
        }
        if (i < buf.len) {
            var rem = self.nextU64();
            while (i < buf.len) : (i += 1) {
                buf[i] = @truncate(rem);
                rem >>= 8;
            }
        }
    }

    pub fn seedFromEntropy(self: *PRNG, allocator: *mem.Allocator) !void {
        self.allocator = allocator;
        var buf = try allocator.alloc(u8, 32);
        defer allocator.free(buf);
        std.crypto.random.bytes(buf);
        var seed: u64 = 0;
        for (buf) |b| {
            seed = (seed << 8) | b;
        }
        self.state[0] = seed;
        self.state[1] = self.nextU64();
        self.state[2] = self.nextU64();
        self.state[3] = self.nextU64();
    }
