pub fn sliceFromBytes(comptime T: type, bytes: []const u8, allocator: *mem.Allocator) ![]T {
    if (bytes.len % @sizeOf(T) != 0) return error.InvalidLength;
    const len = bytes.len / @sizeOf(T);
    const slice = try allocator.alloc(T, len);
    for (0..len) |i| {
        slice[i] = mem.readIntLittle(T, bytes[i * @sizeOf(T)..][0..@sizeOf(T)]);
    }
    return slice;
}

pub fn bytesFromSlice(comptime T: type, slice: []const T, allocator: *mem.Allocator) ![]u8 {
    const len = slice.len * @sizeOf(T);
    const bytes = try allocator.alloc(u8, len);
    for (0..slice.len) |i| {
        mem.writeIntLittle(T, bytes[i * @sizeOf(T)..][0..@sizeOf(T)], slice[i]);
    }
    return bytes;
}

