pub const Arena = struct {
    buffer: []u8,
    offset: usize = 0,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, size: usize) !Arena {
        const buffer = try allocator.alloc(u8, size);
        return .{ .buffer = buffer, .allocator = allocator };
    }

    pub fn deinit(self: *Arena) void {
        self.allocator.free(self.buffer);
    }

    pub fn alloc(self: *Arena, comptime T: type, count: usize) ![]T {
        const needed = count * @sizeOf(T);
        if (self.offset + needed > self.buffer.len) return error.OutOfMemory;
        const ptr = @ptrCast([*]T, @alignCast(self.buffer[self.offset..]));
        const slice = ptr[0..count];
        self.offset += needed;
        return slice;
    }

    pub fn alignedAlloc(self: *Arena, comptime T: type, count: usize, alignment: usize) ![]T {
        const size = count * @sizeOf(T);
        const aligned_offset = types.alignUp(self.offset, alignment);
        const needed = aligned_offset - self.offset + size;
        if (aligned_offset + size > self.buffer.len) return error.OutOfMemory;
        const ptr = @ptrCast([*]T, @alignCast(self.buffer[aligned_offset..]));
        const slice = ptr[0..count];
        self.offset = aligned_offset + size;
        return slice;
    }

    pub fn reset(self: *Arena) void {
        self.offset = 0;
    }

    pub fn used(self: *Arena) usize {
        return self.offset;
    }

    pub fn remaining(self: *Arena) usize {
        return self.buffer.len - self.offset;
    }
};

pub const SlabAllocator = struct {
    slabs: []Slab,
    free_list: usize = 0,
    allocator: *mem.Allocator,

    const Slab = struct {
        objects: []u8,
        in_use: types.BitSet,
        object_size: usize,
        num_objects: usize,
    };

    pub fn init(allocator: *mem.Allocator, object_size: usize, initial_slabs: usize) !SlabAllocator {
        const slabs = try allocator.alloc(Slab, initial_slabs);
        for (slabs) |*slab| {
            slab.objects = try allocator.alloc(u8, object_size * 64);
            slab.in_use = try types.BitSet.init(allocator, 64);
            slab.object_size = object_size;
            slab.num_objects = 64;
        }
        return .{ .slabs = slabs, .allocator = allocator };
    }

    pub fn deinit(self: *SlabAllocator) void {
        for (self.slabs) |slab| {
            slab.in_use.deinit();
            self.allocator.free(slab.objects);
        }
        self.allocator.free(self.slabs);
    }

    pub fn alloc(self: *SlabAllocator) ?[*]u8 {
        while (self.free_list < self.slabs.len) {
            var slab = &self.slabs[self.free_list];
            if (!slab.in_use.count() == slab.num_objects) {
                for (0..slab.num_objects) |i| {
                    if (!slab.in_use.test(i)) {
                        slab.in_use.set(i);
                        return slab.objects[i * slab.object_size ..][0..slab.object_size].ptr;
                    }
                }
            }
            self.free_list += 1;
        }
        return null;
    }

    pub fn free(self: *SlabAllocator, ptr: [*]u8) void {
        for (self.slabs) |*slab| {
            const offset = @ptrToInt(ptr) - @ptrToInt(slab.objects.ptr);
            if (offset % slab.object_size == 0 and offset / slab.object_size < slab.num_objects) {
                const idx = offset / slab.object_size;
                slab.in_use.unset(idx);
                return;
            }
        }
    }

    pub fn grow(self: *SlabAllocator, new_slabs: usize) !void {
        const old_len = self.slabs.len;
        try self.allocator.resize(self.slabs, new_slabs);
        for (old_len..new_slabs) |i| {
            self.slabs[i] = try initSlab(self.allocator, self.slabs[0].object_size);
        }
        self.free_list = old_len;
    }

    fn initSlab(allocator: *mem.Allocator, object_size: usize) !Slab {
        const objects = try allocator.alloc(u8, object_size * 64);
        const in_use = try types.BitSet.init(allocator, 64);
        return .{ .objects = objects, .in_use = in_use, .object_size = object_size, .num_objects = 64 };
    }
};

pub const PoolAllocator = struct {
    buffer: []u8,
    block_size: usize,
    num_blocks: usize,
    free_heads: []usize,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, total_size: usize, block_size: usize) !PoolAllocator {
        const num_blocks = total_size / block_size;
        const buffer = try allocator.alloc(u8, total_size);
        const free_heads = try allocator.alloc(usize, num_blocks);
        @memset(free_heads, 0);
        var head: usize = 0;
        for (free_heads) |*fh| {
            fh.* = head;
            head += block_size;
        }
        return .{ .buffer = buffer, .block_size = block_size, .num_blocks = num_blocks, .free_heads = free_heads, .allocator = allocator };
    }

    pub fn deinit(self: *PoolAllocator) void {
        self.allocator.free(self.buffer);
        self.allocator.free(self.free_heads);
    }

    pub fn alloc(self: *PoolAllocator) ?[]u8 {
        if (self.free_heads[0] == 0) return null;
        const block_idx = 0;
        const offset = self.free_heads[block_idx];
        if (offset == 0) return null;
        self.free_heads[block_idx] = self.free_heads[offset / self.block_size];
        return self.buffer[offset..offset + self.block_size];
    }

    pub fn free(self: *PoolAllocator, slice: []u8) void {
        const offset = @ptrToInt(slice.ptr) - @ptrToInt(self.buffer.ptr);
        if (offset % self.block_size != 0) return;
        const block_idx = offset / self.block_size;
        self.free_heads[block_idx] = self.free_heads[0];
        self.free_heads[0] = block_idx;
    }

    pub fn reset(self: *PoolAllocator) void {
        @memset(self.free_heads, 0);
        var head: usize = 0;
        for (self.free_heads) |*fh| {
            fh.* = head;
            head += self.block_size;
        }
    }
};

pub const LockFreeFreelist = struct {
    head: atomic.Atomic(usize),
    nodes: []Node,
    allocator: *mem.Allocator,

    const Node = struct {
        next: atomic.Atomic(usize),
        data: [64]u8,
    };

    pub fn init(allocator: *mem.Allocator, num_nodes: usize) !LockFreeFreelist {
        const nodes = try allocator.alloc(Node, num_nodes);
        for (0..num_nodes - 1) |i| {
            nodes[i].next.store(i + 1, .SeqCst);
        }
        nodes[num_nodes - 1].next.store(usize.max, .SeqCst);
        return .{ .head = atomic.Atomic(usize).init(0), .nodes = nodes, .allocator = allocator };
    }

    pub fn deinit(self: *LockFreeFreelist) void {
        self.allocator.free(self.nodes);
    }

    pub fn alloc(self: *LockFreeFreelist) ?*Node {
        while (true) {
            const old_head = self.head.load(.Acquire);
            if (old_head == usize.max) return null;
            const next = self.nodes[old_head].next.load(.Acquire);
            if (self.head.compareExchange(old_head, next, .Release, .Monotonic, .Monotonic) == null) {
                return &self.nodes[old_head];
            }
        }
    }

    pub fn free(self: *LockFreeFreelist, node_idx: usize) void {
        while (true) {
            const old_head = self.head.load(.Acquire);
            self.nodes[node_idx].next.store(old_head, .Release);
            if (self.head.compareExchange(old_head, node_idx, .Release, .Monotonic, .Monotonic) != null) {
                return;
            }
        }
    }
};

pub const PageAlignedBuffer = struct {
    pages: []u8,
    page_size: usize,
    num_pages: usize,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, num_pages: usize, page_size: usize) !PageAlignedBuffer {
        const total_size = num_pages * page_size;
        const pages = try allocator.alignedAlloc(u8, page_size, total_size);
        return .{ .pages = pages, .page_size = page_size, .num_pages = num_pages, .allocator = allocator };
    }

    pub fn deinit(self: *PageAlignedBuffer) void {
        self.allocator.free(self.pages);
    }

    pub fn getPage(self: *PageAlignedBuffer, page_idx: usize) []u8 {
        if (page_idx >= self.num_pages) return &.{};
        const offset = page_idx * self.page_size;
        return self.pages[offset..offset + self.page_size];
    }

    pub fn mapRange(self: *PageAlignedBuffer, start_page: usize, num_pages: usize) []u8 {
        if (start_page + num_pages > self.num_pages) return &.{};
        const start = start_page * self.page_size;
        const end = start + num_pages * self.page_size;
        return self.pages[start..end];
    }

    pub fn zeroPage(self: *PageAlignedBuffer, page_idx: usize) void {
        const page = self.getPage(page_idx);
        @memset(page, 0);
    }

    pub fn copyToPage(self: *PageAlignedBuffer, page_idx: usize, src: []const u8) void {
        const page = self.getPage(page_idx);
        if (src.len > page.len) return;
        @memcpy(page[0..src.len], src);
    }
};

pub const ZeroCopySlice = struct {
    base: [*]u8,
    len: usize,
    view_len: usize,

    pub fn fromSlice(slice: []u8) ZeroCopySlice {
        return .{ .base = slice.ptr, .len = slice.len, .view_len = slice.len };
    }

    pub fn slice(self: ZeroCopySlice, start: usize, end: usize) ZeroCopySlice {
        const new_len = math.min(end - start, self.view_len - start);
        return .{ .base = self.base + start, .len = self.len - start, .view_len = new_len };
    }

    pub fn asSlice(self: ZeroCopySlice, comptime T: type) []T {
        return @ptrCast(self.base[0..self.view_len :T]);
    }

    pub fn hash(self: ZeroCopySlice) u64 {
        var hasher = std.hash.Wyhash.init(0);
        hasher.update(self.base[0..self.view_len]);
        return hasher.final();
    }

    pub fn equal(self: ZeroCopySlice, other: ZeroCopySlice) bool {
        if (self.view_len != other.view_len) return false;
        return mem.eql(u8, self.base[0..self.view_len], other.base[0..other.view_len]);
    }
};

pub fn resizeBuffer(allocator: *mem.Allocator, old: []u8, new_size: usize, alignment: usize) ![]u8 {
    if (old.len == new_size) return old;
    const new_buf = try allocator.alignedAlloc(u8, alignment, new_size);
    if (old.len > 0) {
        @memcpy(new_buf[0..math.min(old.len, new_size)], old);
        allocator.free(old);
    }
    return new_buf;
}

pub fn pageAlignAlloc(allocator: *mem.Allocator, size: usize, page_size: usize) ![]u8 {
    const aligned_size = types.alignUp(size, page_size);
    return try allocator.alignedAlloc(u8, page_size, aligned_size);
}

pub fn atomicAlloc(allocator: *mem.Allocator, comptime T: type, count: usize) !*atomic.Atomic([]T) {
    const slice = try allocator.alloc(T, count);
    const ptr = try allocator.create(atomic.Atomic([]T));
    ptr.* = atomic.Atomic([]T).init(slice);
    return ptr;
}

pub fn lockFreePool(comptime T: type, capacity: usize) type {
    return struct {
        pool: [capacity]T,
        free_head: atomic.Atomic(usize),
        in_use: atomic.Atomic(usize),

        pub fn init() @This() {
            return .{ .free_head = atomic.Atomic(usize).init(0), .in_use = atomic.Atomic(usize).init(0) };
        }

        pub fn alloc(self: *@This()) ?*T {
            while (true) {
                const head = self.free_head.load(.Acquire);
                if (head >= capacity) return null;
                const next = if (head + 1 < capacity) head + 1 else usize.max;
                if (self.free_head.compareExchange(head, next, .Release, .Monotonic, .Monotonic) == null) {
                    _ = self.in_use.fetchAdd(1, .Release);
                    return &self.pool[head];
                }
            }
        }

        pub fn free(self: *@This(), ptr: *T) void {
            const idx = @ptrToInt(ptr) - @ptrToInt(&self.pool[0]);
            while (true) {
                const head = self.free_head.load(.Acquire);
                if (head == usize.max) break;
                ptr.next.store(head, .Release);
                if (self.free_head.compareExchange(head, @intCast(idx), .Release, .Monotonic, .Monotonic) == null) {
                    _ = self.in_use.fetchSub(1, .Release);
                    return;
                }
            }
        }
    };
}
