// path: src/core/types.zig
const std = @import("std");
const math = std.math;
const mem = std.mem;
const meta = std.meta;
const rand = std.rand;

pub const Fixed3232 = packed struct {
    raw: u64,

    pub fn init(value: f32) Fixed3232 {
        const int_part = @as(u32, @intFromFloat(math.floor(value)));
        const frac_part = @as(u32, @intFromFloat((value - @as(f32, @floatFromInt(int_part))) * 4294967296.0));
        return .{ .raw = (@as(u64, int_part) << 32) | frac_part };
    }

    pub fn toF32(self: Fixed3232) f32 {
        const int_part = @as(f32, @floatFromInt(@as(u32, @intCast(self.raw >> 32))));
        const frac_part = @as(f32, @floatFromInt(@as(u32, @intCast(self.raw & 0xFFFFFFFF)))) / 4294967296.0;
        return int_part + frac_part;
    }

    pub fn add(self: Fixed3232, other: Fixed3232) Fixed3232 {
        return .{ .raw = self.raw + other.raw };
    }

    pub fn sub(self: Fixed3232, other: Fixed3232) Fixed3232 {
        return .{ .raw = self.raw - other.raw };
    }

    pub fn mul(self: Fixed3232, other: Fixed3232) Fixed3232 {
        const hi = @as(u64, @intCast((@as(u128, self.raw) * @as(u128, other.raw)) >> 64));
        return .{ .raw = hi };
    }

    pub fn div(self: Fixed3232, other: Fixed3232) Fixed3232 {
        const self_f = self.toF32();
        const other_f = other.toF32();
        return init(self_f / other_f);
    }
};

pub const ContextWindow = struct {
    width: usize,
    segments: []RankedSegment,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, width: usize) !ContextWindow {
        var self = ContextWindow{
            .width = width,
            .segments = try allocator.alloc(RankedSegment, 0),
            .allocator = allocator,
        };
        return self;
    }

    pub fn deinit(self: *ContextWindow) void {
        self.allocator.free(self.segments);
    }

    pub fn addSegment(self: *ContextWindow, segment: RankedSegment) !void {
        const new_len = self.segments.len + 1;
        try self.segments = self.allocator.realloc(self.segments, new_len);
        self.segments[new_len - 1] = segment;
    }

    pub fn getTopK(self: *ContextWindow, k: usize) []RankedSegment {
        var heap = std.heap.priorityQueue(RankedSegment, void, rankerCmp);
        defer heap.deinit();
        for (self.segments) |seg| {
            heap.add(seg) catch unreachable;
        }
        var topk = try self.allocator.alloc(RankedSegment, k);
        for (0..k) |i| {
            if (heap.removeOrNull()) |seg| {
                topk[i] = seg;
            } else break;
        }
        return topk;
    }

    fn rankerCmp(_: void, a: RankedSegment, b: RankedSegment) math.Order {
        return math.order(a.score, b.score);
    }
};

pub const RankedSegment = struct {
    start: usize,
    end: usize,
    score: f32,
    anchors: BitSet,

    pub fn init(start: usize, end: usize, score: f32, anchors: BitSet) RankedSegment {
        return .{ .start = start, .end = end, .score = score, .anchors = anchors };
    }
};

pub const BitSet = struct {
    bits: []u64,
    len: usize,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, len: usize) !BitSet {
        const num_words = (len + 63) / 64;
        const bits = try allocator.alloc(u64, num_words);
        @memset(bits, 0);
        return .{ .bits = bits, .len = len, .allocator = allocator };
    }

    pub fn deinit(self: *BitSet) void {
        self.allocator.free(self.bits);
    }

    pub fn set(self: *BitSet, index: usize) void {
        if (index >= self.len) return;
        const word = index / 64;
        const bit = @as(u6, @intCast(index % 64));
        self.bits[word] |= (@as(u64, 1) << bit);
    }

    pub fn unset(self: *BitSet, index: usize) void {
        if (index >= self.len) return;
        const word = index / 64;
        const bit = @as(u6, @intCast(index % 64));
        self.bits[word] &= ~(@as(u64, 1) << bit);
    }

    pub fn test(self: *const BitSet, index: usize) bool {
        if (index >= self.len) return false;
        const word = index / 64;
        const bit = @as(u6, @intCast(index % 64));
        return (self.bits[word] & (@as(u64, 1) << bit)) != 0;
    }

    pub fn count(self: *const BitSet) usize {
        var count: usize = 0;
        for (self.bits) |word| {
            count += @popCount(word);
        }
        return count;
    }

    pub fn or_(self: *BitSet, other: *const BitSet) void {
        const min_words = @min(self.bits.len, other.bits.len);
        for (0..min_words) |i| {
            self.bits[i] |= other.bits[i];
        }
    }

    pub fn and_(self: *BitSet, other: *const BitSet) void {
        const min_words = @min(self.bits.len, other.bits.len);
        for (0..min_words) |i| {
            self.bits[i] &= other.bits[i];
        }
    }

    pub fn xor(self: *BitSet, other: *const BitSet) void {
        const min_words = @min(self.bits.len, other.bits.len);
        for (0..min_words) |i| {
            self.bits[i] ^= other.bits[i];
        }
    }

    pub fn copy(self: *const BitSet, allocator: *mem.Allocator) !BitSet {
        const num_words = self.bits.len;
        const bits = try allocator.alloc(u64, num_words);
        @memcpy(bits, self.bits);
        return .{ .bits = bits, .len = self.len, .allocator = allocator };
    }

    pub fn resize(self: *BitSet, new_len: usize) !void {
        const old_num_words = self.bits.len;
        const new_num_words = (new_len + 63) / 64;
        if (new_num_words > old_num_words) {
            self.bits = try self.allocator.realloc(self.bits, new_num_words);
            @memset(self.bits[old_num_words..], 0);
        } else if (new_num_words < old_num_words) {
            self.bits = self.allocator.realloc(self.bits, new_num_words) catch unreachable;
        }
        self.len = new_len;
    }

    pub fn intersect(self: *const BitSet, other: *const BitSet) usize {
        var count: usize = 0;
        const min_words = @min(self.bits.len, other.bits.len);
        for (0..min_words) |i| {
            count += @popCount(self.bits[i] & other.bits[i]);
        }
        return count;
    }

    pub fn unionSize(self: *const BitSet, other: *const BitSet) usize {
        var count: usize = 0;
        const min_words = @min(self.bits.len, other.bits.len);
        for (0..min_words) |i| {
            count += @popCount(self.bits[i] | other.bits[i]);
        }
        return count;
    }

    pub fn equals(self: *const BitSet, other: *const BitSet) bool {
        const min_words = @min(self.bits.len, other.bits.len);
        for (0..min_words) |i| {
            if (self.bits[i] != other.bits[i]) return false;
        }
        if (self.bits.len != other.bits.len) return false;
        return true;
    }

    pub fn hash(self: *const BitSet) u64 {
        var hasher = std.hash.Wyhash.init(0);
        for (self.bits) |word| {
            hasher.update(&word);
        }
        return hasher.final();
    }

    pub fn toArray(self: *const BitSet, allocator: *mem.Allocator) ![]usize {
        var indices = std.ArrayList(usize).init(allocator);
        defer indices.deinit();
        for (0..self.len) |i| {
            if (self.test(i)) {
                try indices.append(i);
            }
        }
        return try indices.toOwnedSlice();
    }

    pub fn fromArray(allocator: *mem.Allocator, indices: []const usize) !BitSet {
        var bs = try init(allocator, if (indices.len > 0) @max(indices[indices.len - 1] + 1, 64) else 64);
        for (indices) |idx| {
            bs.set(idx);
        }
        return bs;
    }
};

pub const PRNG = struct {
    state: [4]u64,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, seed: u64) !PRNG {
        var self = PRNG{ .state = undefined, .allocator = allocator };
        var hasher = std.hash.Wyhash.init(seed);
        for (&self.state) |*s| {
            s.* = hasher.final();
        }
        return self;
    }

    pub fn deinit(self: *PRNG) void {
        _ = self;
    }

    pub fn nextU64(self: *PRNG) u64 {
        var s = self.state;
        const result = std.math.rotr(u64, s[1] * 5, 7) * 9;
        const t = s[1] << 17;
        s[2] ^= s[0];
        s[3] ^= s[1];
        s[1] ^= s[2];
        s[0] ^= s[3];
        s[2] ^= t;
        s[3] = std.math.rotr(u64, s[3], 45);
        self.state = s;
        return result;
    }

    pub fn nextF32(self: *PRNG) f32 {
        return @as(f32, @floatFromInt(self.nextU64() >> 32)) / @as(f32, @floatFromInt(std.math.maxInt(u32)));
    }

    pub fn fillBytes(self: *PRNG, buf: []u8) void {
        var i: usize = 0;
        while (i + 8 <= buf.len) : (i += 8) {
            mem.writeIntLittle(u64, buf[i..i + 8], self.nextU64());
        }
        if (i < buf.len) {
            var rem = self.nextU64();
            while (i < buf.len) : (i += 1) {
                buf[i] = @as(u8, @intCast(rem));
                rem >>= 8;
            }
        }
    }

    pub fn shuffle(self: *PRNG, slice: []usize) void {
        var i: usize = slice.len;
        while (i > 1) : (i -= 1) {
            const j = self.intInRange(usize, i);
            mem.swap(usize, &slice[i - 1], &slice[j]);
        }
    }

    pub fn intInRange(self: *PRNG, comptime T: type, n: T) T {
        const bits_needed = std.math.ceilLog2(n);
        const mask = (@as(T, 1) << @min(bits_needed, @typeInfo(T).Int.bits)) - 1;
        var value: T = 0;
        while (true) {
            value = @as(T, @intCast(self.nextU64() & mask));
            if (value < n) return value;
        }
    }

    pub fn uniformF32InRange(self: *PRNG, min: f32, max: f32) f32 {
        return self.nextF32() * (max - min) + min;
    }

    pub fn normalF32(self: *PRNG, mean: f32, stddev: f32) f32 {
        var u = self.nextF32();
        var v = self.nextF32();
        const z = math.sqrt(-2.0 * math.log(u)) * math.cos(2.0 * math.pi * v);
        return mean + stddev * z;
    }

    pub fn seed(self: *PRNG, new_seed: u64) void {
        var hasher = std.hash.Wyhash.init(new_seed);
        for (&self.state) |*s| {
            s.* = hasher.final();
        }
    }

    pub fn fork(self: *PRNG, allocator: *mem.Allocator) !PRNG {
        var child = try init(allocator, self.nextU64());
        return child;
    }

    pub fn jump(self: *PRNG) void {
        var step: [4]u64 = .{ 0x180ec6d33cfd0aba, 0xd5a61266f0c9392c, 0xa9582618e03fc9aa, 0x39abdc4529b1661c };
        var s = self.state;
        for (0..4) |i| {
            for (0..4) |j| {
                s[i] ^= step[j];
            }
            _ = self.nextU64();
        }
        self.state = s;
    }

    pub fn advance(self: *PRNG, steps: u64) void {
        var i: u64 = 0;
        while (i < steps) : (i += 1) {
            _ = self.nextU64();
        }
    }

    pub fn splitmix(self: *PRNG) u64 {
        var z = self.state[1];
        z |= (z >> 30);
        z *= 0xbf58476d1ce4e5b9;
        z = (z ^ (z >> 27)) * 0x94d049bb133111eb;
        return z ^ (z >> 31);
    }

    pub fn reseed(self: *PRNG, entropy: []const u8) void {
        var hasher = std.hash.Wyhash.init(0);
        hasher.update(entropy);
        const base = hasher.final();
        self.state[0] = base;
        self.state[1] = self.splitmix();
        self.state[2] = self.splitmix();
        self.state[3] = self.splitmix();
    }

    pub fn bytesToSeed(bytes: []const u8) u64 {
        var hasher = std.hash.Wyhash.init(0);
        hasher.update(bytes);
        return hasher.final();
    }
