pub const TensorShape = struct {
    dims: []usize,
    strides: []usize,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, dims: []const usize) !TensorShape {
        var self = TensorShape{
            .dims = undefined,
            .strides = undefined,
            .allocator = allocator,
        };
        self.dims = try allocator.dupe(usize, dims);
        var stride: usize = 1;
        self.strides = try allocator.alloc(usize, dims.len);
        for (dims.len..0) |i| {
            const idx = i - 1;
            self.strides[idx] = stride;
            stride *= dims[idx];
        }
        return self;
    }

    pub fn deinit(self: *TensorShape) void {
        self.allocator.free(self.dims);
        self.allocator.free(self.strides);
    }

    pub fn size(self: *const TensorShape) usize {
        var sz: usize = 1;
        for (self.dims) |d| sz *= d;
        return sz;
    }

    pub fn broadcast(self: *TensorShape, other: *const TensorShape, allocator: *mem.Allocator) !TensorShape {
        if (self.dims.len != other.dims.len) return error.ShapeMismatch;
        var new_dims = try allocator.alloc(usize, self.dims.len);
        for (0..self.dims.len) |i| {
            if (self.dims[i] == other.dims[i]) {
                new_dims[i] = self.dims[i];
            } else if (self.dims[i] == 1) {
                new_dims[i] = other.dims[i];
            } else if (other.dims[i] == 1) {
                new_dims[i] = self.dims[i];
            } else return error.BroadcastError;
        }
        return try init(allocator, new_dims);
    }

    pub fn permute(self: *TensorShape, axes: []const usize, allocator: *mem.Allocator) !TensorShape {
        var new_dims = try allocator.alloc(usize, self.dims.len);
        for (0..self.dims.len) |i| {
            new_dims[i] = self.dims[axes[i]];
        }
        var new_strides = try allocator.alloc(usize, self.dims.len);
        var stride: usize = 1;
        for (self.dims.len..0) |i| {
            const idx = i - 1;
            const orig_idx = axes[idx];
            new_strides[idx] = stride;
            stride *= self.dims[orig_idx];
        }
        var shape = try init(allocator, new_dims);
        shape.strides = new_strides;
        return shape;
    }

    pub fn contiguous(self: *TensorShape, allocator: *mem.Allocator) !TensorShape {
        var shape = try init(allocator, self.dims);
        var stride: usize = 1;
        for (shape.dims.len..0) |i| {
            const idx = i - 1;
            shape.strides[idx] = stride;
            stride *= shape.dims[idx];
        }
        return shape;
    }

    pub fn slice(self: *const TensorShape, starts: []const usize, ends: []const usize, allocator: *mem.Allocator) !TensorShape {
        if (starts.len != self.dims.len or ends.len != self.dims.len) return error.InvalidSlice;
        var new_dims = try allocator.alloc(usize, self.dims.len);
        var new_strides = try allocator.alloc(usize, self.dims.len);
        for (0..self.dims.len) |i| {
            new_dims[i] = ends[i] - starts[i];
            new_strides[i] = self.strides[i];
        }
        var shape = try init(allocator, new_dims);
        shape.strides = new_strides;
        return shape;
    }

    pub fn expand(self: *TensorShape, new_dims: []const usize, allocator: *mem.Allocator) !TensorShape {
        if (self.dims.len + 1 != new_dims.len) return error.InvalidExpand;
        var dims_copy = try allocator.dupe(usize, new_dims);
        var i = dims_copy.len - 1;
        var j = self.dims.len - 1;
        while (i > 0) : (i -= 1) {
            if (j >= 0) {
                if (self.dims[j] != 1 and self.dims[j] != dims_copy[i]) return error.ExpandError;
                j -= 1;
            }
        }
        var shape = try init(allocator, dims_copy);
        @memcpy(shape.strides[1..], self.strides);
        shape.strides[0] = self.strides[0] * self.dims[0];
        return shape;
    }

    pub fn equals(self: *const TensorShape, other: *const TensorShape) bool {
        if (self.dims.len != other.dims.len) return false;
        for (0..self.dims.len) |i| {
            if (self.dims[i] != other.dims[i]) return false;
        }
        return true;
    }

    pub fn hash(self: *const TensorShape) u64 {
        var hasher = std.hash.Wyhash.init(0);
        for (self.dims) |d| {
            hasher.update(std.mem.asBytes(&d));
        }
        return hasher.final();
    }

    pub fn toString(self: *const TensorShape, allocator: *mem.Allocator) ![]u8 {
        var buf = std.ArrayList(u8).init(allocator);
        errdefer buf.deinit();
        try buf.writer().writeAll("[");
        for (self.dims, 0..) |d, i| {
            if (i > 0) try buf.writer().writeAll(", ");
            try buf.writer().print("{}", .{d});
        }
        try buf.writer().writeAll("]");
        return buf.toOwnedSlice();
    }
};

pub const AlignedBuffer = struct {
    ptr: [*]align(32) u8,
    len: usize,
    cap: usize,
    allocator: *mem.Allocator,

    pub fn init(allocator: *mem.Allocator, cap: usize) !AlignedBuffer {
        const aligned_cap = math.alignAnyAlign(32, cap);
        const ptr = try allocator.alignedAlloc(u8, 32, aligned_cap);
        return .{ .ptr = ptr, .len = 0, .cap = aligned_cap, .allocator = allocator };
    }

    pub fn deinit(self: *AlignedBuffer) void {
        self.allocator.free(self.ptr[0..self.cap]);
    }

    pub fn append(self: *AlignedBuffer, data: []const u8) !void {
        if (self.len + data.len > self.cap) {
            const new_cap = self.cap * 2;
            const new_ptr = try self.allocator.alignedRealloc(u8, 32, self.ptr[0..self.cap], new_cap);
            self.ptr = new_ptr;
            self.cap = new_cap;
        }
        @memcpy(self.ptr[self.len..self.len + data.len], data);
        self.len += data.len;
    }

    pub fn slice(self: *AlignedBuffer) []align(32) u8 {
        return self.ptr[0..self.len];
    }

    pub fn clear(self: *AlignedBuffer) void {
        self.len = 0;
    }

    pub fn resize(self: *AlignedBuffer, new_len: usize) !void {
        if (new_len > self.cap) {
            const new_cap = math.alignAnyAlign(32, new_len);
            const new_ptr = try self.allocator.alignedRealloc(u8, 32, self.ptr[0..self.cap], new_cap);
            self.ptr = new_ptr;
            self.cap = new_cap;
        }
        self.len = new_len;
    }

    pub fn copy(self: *AlignedBuffer, allocator: *mem.Allocator) !AlignedBuffer {
        var copy = try init(allocator, self.len);
        @memcpy(copy.ptr[0..self.len], self.ptr[0..self.len]);
        copy.len = self.len;
        return copy;
    }

    pub fn hash(self: *const AlignedBuffer) u64 {
        var hasher = std.hash.Wyhash.init(0);
        hasher.update(self.ptr[0..self.len]);
        return hasher.final();
    }

    pub fn equals(self: *const AlignedBuffer, other: *const AlignedBuffer) bool {
        if (self.len != other.len) return false;
        return mem.eql(u8, self.ptr[0..self.len], other.ptr[0..other.len]);
    }

    pub fn zero(self: *AlignedBuffer) void {
        @memset(self.ptr[0..self.len], 0);
    }

    pub fn asSliceF32(self: *AlignedBuffer) []align(32:0) f32 {
        return mem.sliceAsBytes(self.ptr[0..self.len]).[0..(self.len / @sizeOf(f32))].ptr[0..(self.len / @sizeOf(f32))];
    }

    pub fn asSliceU64(self: *AlignedBuffer) []align(32:0) u64 {
        return mem.sliceAsBytes(self.ptr[0..self.len]).[0..(self.len / @sizeOf(u64))].ptr[0..(self.len / @sizeOf(u64))];
    }
};

