pub const Tensor = struct {
    data: []align(64) u8,
    shape: []const usize,
    strides: []const usize,
    dtype: DType,
    allocator: Allocator,

    pub fn init(allocator: Allocator, shape: []const usize, dtype: DType) !Tensor {
        const size = computeSize(shape, dtype);
        const data = try allocator.alignedAlloc(u8, 64, size);
        @memset(data, 0);
        const strides = try computeStrides(allocator, shape);
        return .{ .data = data, .shape = shape, .strides = strides, .dtype = dtype, .allocator = allocator };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.strides);
    }

    fn computeSize(shape: []const usize, dtype: DType) usize {
        var size: usize = @sizeOf(switch (dtype) {
            .f32 => f32,
            .fixed16 => Fixed16,
            .fixed32 => Fixed32,
        });
        for (shape) |s| size *= s;
        return size;
    }

    fn computeStrides(allocator: Allocator, shape: []const usize) ![]usize {
        const strides = try allocator.alloc(usize, shape.len);
        var stride: usize = 1;
        var i = shape.len;
        while (i > 0) {
            i -= 1;
            strides[i] = stride;
            stride *= shape[i];
        }
        return strides;
    }

    pub fn getPtr(self: *const Tensor, indices: []const usize) [*]u8 {
        var offset: usize = 0;
        for (indices, 0..) |idx, i| {
            offset += idx * self.strides[i];
        }
        return @ptrCast(self.data.ptr + offset);
    }

    pub fn get(self: *const Tensor, indices: []const usize) switch(DType) { .f32 => f32, .fixed16 => Fixed16, .fixed32 => Fixed32 } {
        const ptr = self.getPtr(indices);
        return switch (self.dtype) {
            .f32 => ptr[0..@sizeOf(f32)].*,
            .fixed16 => ptr[0..@sizeOf(Fixed16)].*,
            .fixed32 => ptr[0..@sizeOf(Fixed32)].*,
        };
    }

    pub fn set(self: *Tensor, indices: []const usize, value: anytype) void {
        const ptr = self.getPtr(indices);
        ptr[0..@sizeOf(@TypeOf(value))].* = value;
    }

    pub fn reshape(self: *Tensor, new_shape: []const usize) !void {
        if (!isCompatibleShape(self.shape, new_shape)) return error.ShapeMismatch;
        self.allocator.free(self.strides);
        self.strides = try computeStrides(self.allocator, new_shape);
        self.shape = new_shape;
    }

    fn isCompatibleShape(old: []const usize, new: []const usize) bool {
        var old_size: usize = 1;
        var new_size: usize = 1;
        for (old) |s| old_size *= s;
        for (new) |s| new_size *= s;
        return old_size == new_size;
    }
};

