        }
        block_ptr[blocks_per_chunk - 1].next = null;
        free_list.push(block_ptr);
        return .{ .block_size = block_size, .blocks_per_chunk = blocks_per_chunk, .free_list = free_list, .chunks = chunks, .allocator = allocator };
    }

    pub fn deinit(self: *Pool) void {
        for (self.chunks.items) |chunk| {
            self.allocator.free(chunk);
        }
        self.chunks.deinit();
    }

    pub fn alloc(self: *Pool) !*anyopaque {
        if (self.free_list.pop()) |node| {
