        try self.chunks.append(chunk);
        var block_ptr = @ptrCast(*Block, chunk.ptr);
        for (0..self.blocks_per_chunk - 1) |i| {
            block_ptr[i].next = @ptrCast(*Block, chunk.ptr + (i + 1) * self.block_size);
        }
        block_ptr[self.blocks_per_chunk - 1].next = null;
        self.free_list.push(block_ptr);
        return self.alloc() catch unreachable;
    }

    pub fn free(self: *Pool, ptr: *anyopaque) void {
        const block = @ptrCast(*Block, @alignCast(@alignOf(*Block), ptr));
        self.free_list.push(block);
    }
};

