pub const Ranker = struct {
    ssi_index: *ssi.SuccinctSemanticIndex,
    window: types.ContextWindow,
    prng: types.PRNG,

    pub fn init(index: *ssi.SuccinctSemanticIndex) Ranker {
        return .{ .ssi_index = index, .window = types.ContextWindow.init(), .prng = types.PRNG.init(42) };
    }

    pub fn rank(self: *Ranker, tokens: []const u64, k: usize, allocator: Allocator) ![]types.RankedSegment {
        for (tokens) |token| {
            self.window.push(token);
        }
        const query_len = @min(tokens.len, 128);
        const query = self.window.buffer[self.window.head - query_len .. self.window.head];
        return try self.ssi_index.retrieveSegments(query, k, allocator);
    }

    pub fn scoreNgram(a: []const u64, b: []const u64) f32 {
        var overlap: usize = 0;
        for (a, 0..) |token_a, i| {
            for (b, 0..) |token_b, j| {
                if (i + j >= b.len) break;
                if (token_a == b[j]) overlap += 1;
            }
        }
        return @as(f32, @floatFromInt(overlap)) / @as(f32, @floatFromInt(@max(a.len, b.len)));
    }

    pub fn lshSimilarity(a: u64, b: u64) f32 {
        return 1.0 - @as(f32, @floatFromInt(@popCount(a ^ b))) / 64.0;
    }
};
