    t_weight: Tensor,
    allocator: Allocator,

    pub fn init(allocator: Allocator, dim: usize) !ReversibleScatterFlow {
        var s_weight = try Tensor.init(allocator, &.{ dim, dim }, .f32);
        var t_weight = try Tensor.init(allocator, &.{ dim, dim }, .f32);
        const prng = types.PRNG.init(123);
        for (s_weight.data) |*val| {
            val.* = prng.float() * 0.02 - 0.01;
        }
        for (t_weight.data) |*val| {
            val.* = prng.float() * 0.02 - 0.01;
        }
        return .{ .s_weight = s_weight, .t_weight = t_weight, .allocator = allocator };
    }

    pub fn forward(self: *ReversibleScatterFlow, x1: *Tensor, x2: *Tensor, y1: *Tensor, y2: *Tensor) !void {
        var s = try tensor.matmul(x2, &self.s_weight, self.allocator);
        defer s.deinit();
        try tensor.exp(&s);
        try tensor.mul(x1, &s);
        @memcpy(y1.data, x1.data);
        var t = try tensor.matmul(y1, &self.t_weight, self.allocator);
        defer t.deinit();
        try tensor.add(x2, &t);
        @memcpy(y2.data, x2.data);
    }

    pub fn backward(self: *ReversibleScatterFlow, y1: *Tensor, y2: *Tensor, x1: *Tensor, x2: *Tensor) !void {
        @memcpy(x2.data, y2.data);
        var t = try tensor.matmul(y1, &self.t_weight, self.allocator);
        defer t.deinit();
        try tensor.sub(x2, &t);
        @memcpy(x1.data, y1.data);
        var s = try tensor.matmul(x2, &self.s_weight, self.allocator);
        defer s.deinit();
        try tensor.exp(&s);
        try tensor.div(x1, &s);
    }
};
