pub const MorphoGraphTokenizer = struct {
    trie: std.AutoHashMap(u32, Node),
    allocator: Allocator,

    const Node = struct {
        children: std.AutoHashMap(u8, u32),
        is_end: bool,
        anchor: bool,
    };

    pub fn init(allocator: Allocator) !MorphoGraphTokenizer {
        return .{ .trie = std.AutoHashMap(u32, Node).init(allocator), .allocator = allocator };
    }

    pub fn deinit(self: *MorphoGraphTokenizer) void {
        self.trie.deinit();
    }

    pub fn addWord(self: *MorphoGraphTokenizer, word: []const u8, anchor: bool) !void {
        var node_id: u32 = 0;
        if (!self.trie.get(node_id)) |_| {
            try self.trie.put(node_id, .{ .children = std.AutoHashMap(u8, u32).init(self.allocator), .is_end = false, .anchor = false });
        }
        for (word) |byte| {
            var node = self.trie.getPtr(node_id).?;
            if (!node.children.get(byte)) |child_id| {
                const new_id = @as(u32, @intCast(self.trie.count() + 1));
                try node.children.put(byte, new_id);
                try self.trie.put(new_id, .{ .children = std.AutoHashMap(u8, u32).init(self.allocator), .is_end = false, .anchor = false });
                node_id = new_id;
            } else {
                node_id = child_id;
            }
        }
        var node = self.trie.getPtr(node_id).?;
        node.is_end = true;
        node.anchor = anchor;
    }

    pub fn tokenize(self: *MorphoGraphTokenizer, text: []const u8, allocator: Allocator) ![]u64 {
        var tokens = std.ArrayList(u64).init(allocator);
        var i: usize = 0;
        while (i < text.len) {
            var node_id: u32 = 0;
            var j: usize = i;
            var best_end: ?usize = null;
            var best_anchor = false;
            while (j < text.len) : (j += 1) {
                const byte = text[j];
                if (self.trie.get(node_id)) |node| {
                    if (node.children.get(byte)) |child_id| {
                        node_id = child_id;
                        if (self.trie.get(node_id)) |child_node| {
                            if (child_node.is_end) {
                                best_end = j + 1;
                                best_anchor = child_node.anchor;
                            }
                        }
                    } else break;
                } else break;
            }
            if (best_end) |end| {
                try tokens.append(@as(u64, @intCast(end - i)) | if (best_anchor) @as(u64, 1) << 32 else 0);
                i = end;
            } else {
                try tokens.append(@as(u64, @intCast(text[i])) | @as(u64, 1) << 40);
                i += 1;
            }
        }
        return tokens.toOwnedSlice();
    }
};
