const math = std.math;
const Allocator = std.mem.Allocator;
const Tensor = @import("../core/types.zig").Tensor;

pub const SpectralFisherDiagonalizer = struct {
    fisher_diag: Tensor,
    beta2: f32,
    eps: f32,
    allocator: Allocator,

    pub fn init(allocator: Allocator, param_size: usize) !SpectralFisherDiagonalizer {
        var fisher_diag = try Tensor.init(allocator, &.{param_size}, .f32);
        fisher_diag.fill(1.0);
        return .{ .fisher_diag = fisher_diag, .beta2 = 0.999, .eps = 1e-8, .allocator = allocator };
    }

    pub fn update(self: *SpectralFisherDiagonalizer, grad: *Tensor) !void {
        const len = grad.data.len / @sizeOf(f32);
        const g_ptr = @ptrCast([*]f32, @alignCast(4, grad.data.ptr));
        const f_ptr = @ptrCast([*]f32, @alignCast(4, self.fisher_diag.data.ptr));
        for (0..len) |i| {
            const g = g_ptr[i];
            f_ptr[i] = self.beta2 * f_ptr[i] + (1.0 - self.beta2) * g * g;
            const clipped = math.min(f_ptr[i], 10.0);
            f_ptr[i] = clipped;
        }
    }

    pub fn precondition(self: *SpectralFisherDiagonalizer, grad: *Tensor, lr: f32) !void {
        const len = grad.data.len / @sizeOf(f32);
        const g_ptr = @ptrCast([*]f32, @alignCast(4, grad.data.ptr));
        const f_ptr = @ptrCast([*]f32, @alignCast(4, self.fisher_diag.data.ptr));
        for (0..len) |i| {
            g_ptr[i] = g_ptr[i] / (math.sqrt(f_ptr[i]) + self.eps) * lr;
        }
    }
};
