    cap: u64,
    buffer: [16]Message,
    head: u8,
    tail: u8,

    pub fn init(cap: u64) Channel {
        return .{ .cap = cap, .buffer = undefined, .head = 0, .tail = 0 };
    }

    pub fn send(self: *Channel, msg: Message) bool {
        const next = (self.head + 1) % 16;
        if (next == self.tail) return false;
        self.buffer[self.head] = msg;
        self.head = next;
        _ = kernel.ipcSend(self.cap, @ptrToInt(&self.buffer[self.tail]));
        return true;
    }

    pub fn recv(self: *Channel) ?Message {
        if (self.head == self.tail) return null;
        const msg = self.buffer[self.tail];
        self.tail = (self.tail + 1) % 16;
        return msg;
    }
};
